package vn.edu.eaut.lab10.filter;
import java.io.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import vn.edu.eaut.lab10.model.*;
@WebFilter(urlPatterns={"/admin/*","/staff/*"}) public class AuthorizationFilter implements Filter{public void doFilter(ServletRequest a,ServletResponse b,FilterChain c)throws IOException,ServletException{HttpServletRequest q=(HttpServletRequest)a;HttpServletResponse p=(HttpServletResponse)b;User u=(User)q.getSession().getAttribute("currentUser");String x=q.getRequestURI();if(x.contains("/admin/")&&u.getRole()!=Role.ADMIN){p.sendRedirect(q.getContextPath()+"/error/403.jsp");return;}if(x.contains("/staff/")&&u.getRole()==Role.USER){p.sendRedirect(q.getContextPath()+"/error/403.jsp");return;}c.doFilter(a,b);}}